#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, a;
    cin >> n >> a;
    --a;

    vector<int> criminals(n);
    for (int& x : criminals) cin >> x;

    int answer = criminals[a];

    for (int distance = 1; a - distance >= 0 || a + distance < n; ++distance) {
        int left = a - distance;
        int right = a + distance;

        if (left >= 0 && right < n) {
            if (criminals[left] && criminals[right]) answer += 2;
        } else if (left >= 0) {
            answer += criminals[left];
        } else {
            answer += criminals[right];
        }
    }

    cout << answer << '\n';
    return 0;
}

